     1	package hotel.reservations;
     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.documents.TextFormat;
     5	import hotel.messages.EmailSender;
     6	import hotel.rooms.Room;
     7	import hotel.rooms.Rooms;
     8	import java.math.BigDecimal;
     9	
    10	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    11	public final class ReservationService {
    12	
    13	    static final String HOTEL_NAME = "Pousada Maré Alta";
    14	    static final String HOUSEKEEPING_EMAIL = "governanca@pousadamarealta.com.br";
    15	    static final String FINANCE_EMAIL = "financeiro@pousadamarealta.com.br";
    16	
    17	    private final Rooms rooms;
    18	    private final ReservationStore store;
    19	    private final PriceCalculator priceCalculator;
    20	    private final EmailSender emailSender;
    21	
    22	    public ReservationService(
    23	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    24	        this.rooms = rooms;
    25	        this.store = store;
    26	        this.priceCalculator = priceCalculator;
    27	        this.emailSender = emailSender;
    28	    }
    29	
    30	    public synchronized Reservation create(NewReservation request) {
    31	        if (!request.checkOut().isAfter(request.checkIn())) {
    32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    33	        }
    34	        if (request.guests() < 1) {
    35	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    36	        }
    37	        Room room = rooms.find(request.roomNumber())
    38	                .orElseThrow(() -> new HotelException(
    39	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    40	        if (request.guests() > room.capacity()) {
    41	            throw new HotelException(
    42	                    ErrorCode.CAPACITY_EXCEEDED,
    43	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    44	        }
    45	        boolean roomTaken = store.all().stream()
    46	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
    47	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
    48	        if (roomTaken) {
    49	            throw new HotelException(
    50	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    51	        }
    52	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    53	        Reservation reservation = new Reservation(store.nextId(), request, price);
    54	        store.save(reservation);
    55	        return reservation;
    56	    }
    57	
    58	    public Reservation find(long reservationId) {
    59	        return store.find(reservationId)
    60	                .orElseThrow(() -> new HotelException(
    61	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    62	    }
    63	
    64	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    65	    public synchronized Reservation confirm(long reservationId) {
    66	        Reservation reservation = find(reservationId);
    67	        if (reservation.status() != ReservationStatus.PENDING) {
    68	            throw notAllowed(reservation, "confirm");
    69	        }
    70	        reservation.confirmPayment();
    71	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    72	        emailSender.send(
    73	                reservation.guest().email(),
    74	                "Reserva confirmada - " + HOTEL_NAME,
    75	                confirmationEmailBody(reservation, receipt));
    76	        Room room = roomOf(reservation);
    77	        emailSender.send(HOUSEKEEPING_EMAIL, "Reserva confirmada - quarto " + room.number(),
    78	                "Quarto " + room.number() + " (" + room.type() + ")\n"
    79	                + "Entrada: " + TextFormat.date(reservation.checkIn())
    80	                + " | Saída: " + TextFormat.date(reservation.checkOut()) + "\n"
    81	                + "Hóspedes: " + reservation.guests() + "\n");
    82	        emailSender.send(FINANCE_EMAIL, "Pagamento recebido - reserva " + reservation.id(),
    83	                "Reserva " + reservation.id() + " (" + reservation.guest().name() + "): pagamento de "
    84	                        + TextFormat.money(reservation.amountPaid()) + ".\n");
    85	        return reservation;
    86	    }
    87	
    88	    /**
    89	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    90	     * reservation was never paid, so nothing comes back).
    91	     */
    92	    public synchronized Reservation cancel(long reservationId) {
    93	        Reservation reservation = find(reservationId);
    94	        if (reservation.status() != ReservationStatus.PENDING
    95	                && reservation.status() != ReservationStatus.CONFIRMED) {
    96	            throw notAllowed(reservation, "cancel");
    97	        }
    98	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
    99	        BigDecimal refund = switch (reservation.ratePlan()) {
   100	            case STANDARD -> reservation.amountPaid();
   101	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
   102	        };
   103	        reservation.cancel(refund);
   104	        if (wasConfirmed) {
   105	            int roomNumber = reservation.roomNumber();
   106	            emailSender.send(HOUSEKEEPING_EMAIL, "Reserva cancelada - quarto " + roomNumber,
   107	                    "O quarto " + roomNumber + " ficou livre de " + TextFormat.date(reservation.checkIn())
   108	                            + " a " + TextFormat.date(reservation.checkOut()) + ".\n");
   109	            if (refund.signum() > 0) {
   110	                emailSender.send(FINANCE_EMAIL, "Reembolso - reserva " + reservation.id(),
   111	                        "Devolver " + TextFormat.money(refund) + " para " + reservation.guest().name() + ".\n");
   112	            }
   113	        }
   114	        return reservation;
   115	    }
   116	
   117	    public synchronized Reservation checkIn(long reservationId) {
   118	        Reservation reservation = find(reservationId);
   119	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   120	            throw notAllowed(reservation, "check in");
   121	        }
   122	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   123	        return reservation;
   124	    }
   125	
   126	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   127	    public synchronized ReservationReceipt checkOut(long reservationId) {
   128	        Reservation reservation = find(reservationId);
   129	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   130	            throw notAllowed(reservation, "check out");
   131	        }
   132	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   133	        return new ReservationReceipt(reservation, roomOf(reservation));
   134	    }
   135	
   136	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   137	    public ReservationReceipt receiptCopy(long reservationId) {
   138	        Reservation reservation = find(reservationId);
   139	        if (!reservation.isPaid()) {
   140	            throw notAllowed(reservation, "issue a receipt for");
   141	        }
   142	        return new ReservationReceipt(reservation, roomOf(reservation));
   143	    }
   144	
   145	    private Room roomOf(Reservation reservation) {
   146	        return rooms.find(reservation.roomNumber()).orElseThrow();
   147	    }
   148	
   149	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   150	        return "Olá, " + reservation.guest().name() + "!\n\n"
   151	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   152	                + receipt.text() + "\n"
   153	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   154	                + "Até breve!\n";
   155	    }
   156	
   157	    private static HotelException notAllowed(Reservation reservation, String operation) {
   158	        return new HotelException(
   159	                ErrorCode.OPERATION_NOT_ALLOWED,
   160	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   161	    }
   162	}
     1	package hotel;
     2	
     3	import hotel.messages.EmailSender;
     4	import hotel.messages.SentMessages;
     5	import hotel.reports.OccupancyReport;
     6	import hotel.reports.RevenueReport;
     7	import hotel.reservations.PriceCalculator;
     8	import hotel.reservations.ReservationService;
     9	import hotel.reservations.ReservationStore;
    10	import hotel.rooms.Rooms;
    11	import hotel.web.HttpApi;
    12	import io.javalin.Javalin;
    13	
    14	/** Puts the inn's pieces together and runs the HTTP server. */
    15	public final class Hotel {
    16	
    17	    private final Javalin server;
    18	
    19	    public Hotel() {
    20	        Rooms rooms = new Rooms();
    21	        ReservationStore store = new ReservationStore();
    22	        SentMessages sentMessages = new SentMessages();
    23	        ReservationService reservations =
    24	                new ReservationService(rooms, store, new PriceCalculator(), new EmailSender(sentMessages));
    25	        HttpApi api = new HttpApi(
    26	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
    27	        this.server = api.server();
    28	    }
    29	
    30	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
    31	    public int start(int port) {
    32	        server.start(port);
    33	        return server.port();
    34	    }
    35	
    36	    public void stop() {
    37	        server.stop();
    38	    }
    39	
    40	    public static void main(String[] args) {
    41	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
    42	        new Hotel().start(port);
    43	    }
    44	}
